#!/usr/bin/env node
/**
 * Per-sensor API references: `docs/<sensor>/api.md`, one focused file per
 * sensor mirroring the Python docs tree. Each is generated by pointing TypeDoc
 * at a dedicated entry-point barrel under `typedoc/` that re-exports only that
 * sensor's public symbols, then flattening the emitted tree (via
 * `mergeMarkdownTree`) with a per-sensor header.
 *
 * The ToF is split by class across two files: `vl53l8cx` (the base ToF surface)
 * and `vl53l8ch` (only the CH superset + Compact-Network-Histogram symbols),
 * so no CH symbol bleeds into the CX reference and vice-versa. The shared
 * cross-sensor surface (discovery/device/transport/dataset/…) stays only in the
 * root `docs/api.md`.
 *
 * Run via `bun run docs` (which also regenerates the root api.md). Commit the
 * generated Markdown as source, like the root reference.
 */

import { execFileSync } from "node:child_process";
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { mergeMarkdownTree } from "./merge-api-md.mjs";

const here = path.dirname(fileURLToPath(import.meta.url));
const pkgRoot = path.resolve(here, "..");
const typedocBin = path.join(pkgRoot, "node_modules", ".bin", "typedoc");

/** Header line block shared by every per-sensor api.md. */
function header(title, lead) {
  return [
    `# ${title} — API reference`,
    "",
    ...lead,
    "",
    "Generated from the TypeScript sources by TypeDoc — run `bun run docs` to " +
      "regenerate. Edit the doc comments in the source, not this file.",
    "",
  ];
}

const ROOT_LINK = "[top-level API reference](../api.md)";

// entry = the typedoc/ barrel; dir = docs/<dir>/api.md.
const SENSORS = [
  {
    dir: "sr04",
    entry: "typedoc/entry-sr04.ts",
    header: header("SR04", [
      "The public API for the SR04 ultrasonic sensor. Discovery, device-base,",
      "transport and other cross-sensor symbols shared by every sensor live in",
      `the ${ROOT_LINK}.`,
    ]),
  },
  {
    dir: "vl53l4cd",
    entry: "typedoc/entry-vl53l4cd.ts",
    header: header("VL53L4CD (ToF)", [
      "The VL53L4CD single-zone time-of-flight surface: the `Vl53l4Cd` class,",
      "the host-side ST ULD 2.2.3 driver (`VL53L4CD` + codecs), and the",
      "register-bridge wire codecs. Discovery, device-base, transport and",
      `other cross-sensor symbols shared by every sensor live in the ${ROOT_LINK}.`,
    ]),
  },
  {
    dir: "vl53l8cx",
    entry: "typedoc/entry-vl53l8cx.ts",
    header: header("VL53L8CX (ToF)", [
      "The base VL53L8**CX** time-of-flight surface: the `Vl53l8Cx` class (and",
      "its `Vl53l8` alias), the frame type, and the ST ULD constants/helpers.",
      "The CH superset (`Vl53l8Ch` + Compact-Network-Histogram) has its own",
      "[VL53L8CH reference](../vl53l8ch/api.md); cross-sensor symbols shared by",
      `every sensor live in the ${ROOT_LINK}.`,
    ]),
  },
  {
    dir: "vl53l8ch",
    entry: "typedoc/entry-vl53l8ch.ts",
    header: header("VL53L8CH (ToF)", [
      "CH-specific surface: the `Vl53l8Ch` class (the CX superset that adds",
      "`configureCnh()`) plus the Compact-Network-Histogram (CNH) symbols.",
      "Every base ToF method CH inherits is documented in the",
      "[VL53L8CX reference](../vl53l8cx/api.md); cross-sensor symbols live in",
      `the ${ROOT_LINK}.`,
    ]),
  },
  {
    dir: "bno086",
    entry: "typedoc/entry-bno086.ts",
    header: header("BNO086 (IMU)", [
      "The public API for the BNO086 IMU: the `Bno086` device plus the SHTP /",
      "SH-2 protocol and report types. Discovery, device-base, transport and",
      `other cross-sensor symbols live in the ${ROOT_LINK}.`,
    ]),
  },
];

for (const s of SENSORS) {
  const tmp = mkdtempSync(path.join(tmpdir(), `depz-api-${s.dir}-`));
  try {
    // `notExported: false` silences the expected "referenced but not included"
    // warnings for cross-sensor / shared types the barrel intentionally omits.
    execFileSync(
      typedocBin,
      ["--entryPoints", s.entry, "--out", tmp, "--validation.notExported", "false"],
      { cwd: pkgRoot, stdio: ["ignore", "ignore", "inherit"] },
    );
    const { text, count } = mergeMarkdownTree(tmp, s.header);
    const outFile = path.join(pkgRoot, "docs", s.dir, "api.md");
    mkdirSync(path.dirname(outFile), { recursive: true });
    writeFileSync(outFile, text);
    console.log(`merged ${count} files → docs/${s.dir}/api.md`);
  } finally {
    rmSync(tmp, { recursive: true, force: true });
  }
}
